"use strict";const categories={brick:"Brick walls",paper:"Paper walls",partition:"Partition walls",mindset:"Mindset issues"};const key="breaking-shell-v1";let state={version:1,purpose:"",barriers:[]};const status=document.getElementById("status");try{const s=JSON.parse(localStorage.getItem(key)||"null");if(s&&s.version===1&&Array.isArray(s.barriers)){state={version:1,purpose:String(s.purpose||""),barriers:s.barriers.filter(x=>x&&categories[x.category]).map(x=>({id:String(x.id),text:String(x.text||""),category:x.category,action:String(x.action||"")}))}}}catch{status.textContent="Saved data could not be loaded. You can start a new exercise."}function save(){try{localStorage.setItem(key,JSON.stringify(state));status.textContent="Saved in this browser."}catch{status.textContent="This browser cannot save the exercise. Export JSON to keep your work."}}const purpose=document.getElementById("purpose");purpose.value=state.purpose;purpose.addEventListener("input",()=>{state.purpose=purpose.value;save()});function render(){Object.keys(categories).forEach(c=>document.getElementById(c).replaceChildren());state.barriers.forEach(b=>{const card=document.createElement("article");card.className="card";const p=document.createElement("p");p.textContent=b.text;const label=document.createElement("label");label.textContent="Move to";const select=document.createElement("select");Object.entries(categories).forEach(([v,t])=>{const o=document.createElement("option");o.value=v;o.textContent=t;select.append(o)});select.value=b.category;select.addEventListener("change",()=>{b.category=select.value;save();render()});label.append(select);const al=document.createElement("label");al.textContent="Next action, owner, and date";const a=document.createElement("textarea");a.value=b.action;a.addEventListener("input",()=>{b.action=a.value;save()});al.append(a);const remove=document.createElement("button");remove.className="secondary";remove.textContent="Remove barrier";remove.addEventListener("click",()=>{state.barriers=state.barriers.filter(x=>x.id!==b.id);save();render()});card.append(p,label,al,remove);document.getElementById(b.category).append(card)})}document.getElementById("add").addEventListener("submit",e=>{e.preventDefault();const el=document.getElementById("barrier");if(!el.value.trim())return;state.barriers.push({id:crypto.randomUUID(),text:el.value.trim(),category:document.getElementById("category").value,action:""});el.value="";save();render();el.focus()});document.getElementById("export").onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:"application/json"}));const a=document.createElement("a");a.href=u;a.download="breaking-the-shell.json";a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};document.getElementById("print").onclick=()=>window.print();document.getElementById("clear").onclick=()=>{if(!confirm("Clear the purpose and all barriers from this browser? Export a copy first if you need it."))return;state={version:1,purpose:"",barriers:[]};purpose.value="";save();render()};render();